3	const test = require('node:test');
4	const assert = require('node:assert/strict');
5	const http = require('node:http');
6	const fs = require('node:fs');
7	const os = require('node:os');
8	const path = require('node:path');
9	const crypto = require('node:crypto');
10	const { run } = require('../src/push');
11	
12	function tempDir() {
13	  return fs.mkdtempSync(path.join(os.tmpdir(), 'syncbox-client-test-'));
14	}
15	
16	// A minimal in-memory stand-in for the real Syncbox server: just enough of
17	// GET /blobs and PUT /blobs/{key} for push() to exercise against, without
18	// coupling client tests to the server package.
19	function startFakeServer() {
20	  const store = new Map(); // key -> { buffer, sha256 }
21	  const puts = [];
22	
23	  const server = http.createServer((req, res) => {
24	    const pathname = req.url.split('?')[0];
25	
26	    if (req.method === 'GET' && pathname === '/blobs') {
27	      const list = [...store.entries()].map(([key, blob]) => ({
28	        key,
29	        size: blob.buffer.length,
30	        sha256: blob.sha256,
31	        modified_at: new Date(0).toISOString(),
32	      }));
33	      res.writeHead(200, { 'Content-Type': 'application/json' });
34	      res.end(JSON.stringify(list));
35	      return;
36	    }
37	
38	    const match = pathname.match(/^\/blobs\/(.+)$/);
39	    if (match && req.method === 'PUT') {
40	      const key = decodeURIComponent(match[1]);
41	      const chunks = [];
42	      req.on('data', (c) => chunks.push(c));
43	      req.on('end', () => {
44	        const buffer = Buffer.concat(chunks);
45	        const sha256 = crypto.createHash('sha256').update(buffer).digest('hex');
46	        store.set(key, { buffer, sha256 });
47	        puts.push(key);
48	        res.writeHead(201, { 'Content-Type': 'application/json' });
49	        res.end(JSON.stringify({ key, sha256, size: buffer.length }));
50	      });
51	      return;
52	    }
53	
54	    res.writeHead(404);
55	    res.end();
56	  });
57	
58	  return { server, store, puts };
59	}
60	
61	function listen(server) {
62	  return new Promise((resolve) => {
63	    server.listen(0, '127.0.0.1', () => resolve(server.address().port));
64	  });
65	}
66	
67	test('push uploads every file when the server is empty', async (t) => {
68	  const { server, store, puts } = startFakeServer();
69	  const port = await listen(server);
70	  t.after(() => server.close());
71	
72	  const dir = tempDir();
73	  fs.writeFileSync(path.join(dir, 'a.txt'), 'hello');
74	  fs.mkdirSync(path.join(dir, 'docs'));
75	  fs.writeFileSync(path.join(dir, 'docs', 'readme.txt'), '# readme');
76	
77	  const result = await run({ dir, serverUrl: `http://127.0.0.1:${port}` });
78	
79	  assert.deepEqual(result.uploaded.sort(), ['a.txt', 'docs/readme.txt']);
80	  assert.deepEqual(result.skipped, []);
81	  assert.deepEqual(puts.sort(), ['a.txt', 'docs/readme.txt']);
82	  assert.equal(store.get('a.txt').buffer.toString(), 'hello');
83	  assert.equal(store.get('docs/readme.txt').buffer.toString(), '# readme');
84	});
85	
86	test('push skips a file whose content already matches the server copy', async (t) => {
87	  const { server, puts } = startFakeServer();
88	  const port = await listen(server);
89	  t.after(() => server.close());
90	
91	  const dir = tempDir();
92	  fs.writeFileSync(path.join(dir, 'a.txt'), 'hello');
93	  const serverUrl = `http://127.0.0.1:${port}`;
94	
95	  await run({ dir, serverUrl });
96	  puts.length = 0;
97	
98	  const result = await run({ dir, serverUrl });
99	
100	  assert.deepEqual(result.uploaded, []);
101	  assert.deepEqual(result.skipped, ['a.txt']);
102	  assert.deepEqual(puts, []);
103	});
