105	test('push re-uploads a file whose content changed since the last push', async (t) => {
106	  const { server, store } = startFakeServer();
107	  const port = await listen(server);
108	  t.after(() => server.close());
109	
110	  const dir = tempDir();
111	  const filePath = path.join(dir, 'a.txt');
112	  fs.writeFileSync(filePath, 'hello');
113	  const serverUrl = `http://127.0.0.1:${port}`;
114	
115	  await run({ dir, serverUrl });
116	  fs.writeFileSync(filePath, 'hello, changed');
117	  const result = await run({ dir, serverUrl });
118	
119	  assert.deepEqual(result.uploaded, ['a.txt']);
120	  assert.equal(store.get('a.txt').buffer.toString(), 'hello, changed');
