130	  fs.writeFileSync(path.join(dir, 'a.txt'), 'hello');
131	  await run({ dir, serverUrl });
132	
133	  fs.writeFileSync(path.join(dir, 'b.txt'), 'world');
134	  const result = await run({ dir, serverUrl });
135	
136	  assert.deepEqual(result.uploaded, ['b.txt']);
137	  assert.deepEqual(result.skipped, ['a.txt']);
138	  assert.equal(store.size, 2);
139	});
