141	test('push does not re-upload a same-content file even if the local mtime changed', async (t) => {
142	  const { server, puts } = startFakeServer();
143	  const port = await listen(server);
144	  t.after(() => server.close());
145	
146	  const dir = tempDir();
147	  const filePath = path.join(dir, 'a.txt');
148	  fs.writeFileSync(filePath, 'hello');
